export const protectedOrder=[2,7,12,17,4,9,14,19,1,6,11,16,3,8,13,18];
export function contactNetwork(coverage=0,steps=0){coverage=Math.max(0,Math.min(80,Number(coverage)||0));steps=Math.max(0,Math.min(5,Math.floor(Number(steps)||0)));const protectedNodes=protectedOrder.slice(0,Math.round(coverage/5)),infected=new Set([0]),edges=[];for(let i=0;i<20;i++){if(i%5<4)edges.push([i,i+1]);if(i<15)edges.push([i,i+5]);}for(let r=0;r<steps;r++){let next=new Set(infected);for(let[a,b]of edges){if(infected.has(a)&&!protectedNodes.includes(b))next.add(b);if(infected.has(b)&&!protectedNodes.includes(a))next.add(a);}for(let n of next)infected.add(n);}return{protectedNodes,infected:[...infected],edges,steps,coverage};}
export function selectedCohort(antibiotic=true,step=0){step=Math.max(0,Math.min(2,Math.floor(Number(step)||0)));let susceptible=step===0?18:antibiotic?0:step===1?18:36,resistant=step===0?2:step===1?2:antibiotic?8:4;return{susceptible,resistant,total:susceptible+resistant,percent:100*resistant/(susceptible+resistant),step};}
export const doseData=[{level:0,benefit:0,harm:0},{level:1,benefit:30,harm:2},{level:2,benefit:65,harm:6},{level:3,benefit:70,harm:24}];
export function acceptableDose(level){let d=doseData.find(d=>d.level===Number(level));return!!d&&d.benefit>=60&&d.harm<=10;}
export function percentageDifference(a,na,b,nb){return[a,na,b,nb].every(Number.isFinite)&&na>0&&nb>0&&a>=0&&a<=na&&b>=0&&b<=nb?a/na*100-b/nb*100:null;}
